CREATE DATABASE IF NOT EXISTS flowsync_simple DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE flowsync_simple;
CREATE TABLE IF NOT EXISTS sys_user(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,real_name VARCHAR(50) NOT NULL,role VARCHAR(30) NOT NULL,phone VARCHAR(20),email VARCHAR(100),create_time DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_info(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,description VARCHAR(500),status VARCHAR(20) NOT NULL,priority VARCHAR(20) NOT NULL,owner_id BIGINT,start_date DATE,end_date DATE,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES sys_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS task_info(id BIGINT PRIMARY KEY AUTO_INCREMENT,project_id BIGINT NOT NULL,parent_id BIGINT,title VARCHAR(100) NOT NULL,description VARCHAR(1000),assignee_id BIGINT,creator_id BIGINT,status VARCHAR(20) NOT NULL,priority VARCHAR(20) NOT NULL,due_date DATE,ai_suggestion TEXT,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES project_info(id),FOREIGN KEY(parent_id) REFERENCES task_info(id),FOREIGN KEY(assignee_id) REFERENCES sys_user(id),FOREIGN KEY(creator_id) REFERENCES sys_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS task_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,task_id BIGINT NOT NULL,progress_percent INT NOT NULL,content VARCHAR(1000) NOT NULL,operator_id BIGINT,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(task_id) REFERENCES task_info(id),FOREIGN KEY(operator_id) REFERENCES sys_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS task_summary(id BIGINT PRIMARY KEY AUTO_INCREMENT,project_id BIGINT NOT NULL,task_id BIGINT,summary_type VARCHAR(30) NOT NULL,content VARCHAR(2000) NOT NULL,created_by BIGINT,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES project_info(id),FOREIGN KEY(task_id) REFERENCES task_info(id),FOREIGN KEY(created_by) REFERENCES sys_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS operation_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,operator_id BIGINT,module VARCHAR(50) NOT NULL,action VARCHAR(50) NOT NULL,target_id BIGINT,detail VARCHAR(1000),create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(operator_id) REFERENCES sys_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO sys_user(id,username,password,real_name,role,phone,email) VALUES(1,'admin','123456','系统管理员','负责人','13800000000','admin@flowsync.local'),(2,'leader','123456','项目负责人','负责人','13800000001','leader@flowsync.local'),(3,'member1','123456','张三','成员','13800000002','zhangsan@flowsync.local'),(4,'member2','123456','李四','成员','13800000003','lisi@flowsync.local') ON DUPLICATE KEY UPDATE real_name=VALUES(real_name),role=VALUES(role);
